// Portrait photos — fetched once from randomuser.me, hardcoded as base64.
// Each agent's face is permanent. Never regenerated at runtime.

export const AGENT_PORTRAITS: Record<string, string> = {
  'Marcelo': 'data:image/jpeg;base64,',
  'Ricardo': 'data:image/jpeg;base64,',
  'Lucas': 'data:image/jpeg;base64,',
  'Paulo': 'data:image/jpeg;base64,',
  'Gabriel': 'data:image/jpeg;base64,',
  'Juliana': 'data:image/jpeg;base64,',
  'Bruno': 'data:image/jpeg;base64,',
  'Felipe': 'data:image/jpeg;base64,',
  'Ana': 'data:image/jpeg;base64,',
  'Rafael': 'data:image/jpeg;base64,',
  'Antônio': 'data:image/jpeg;base64,',
  'Pedro': 'data:image/jpeg;base64,',
}

export function getPortrait(name: string): string | undefined {
  if (AGENT_PORTRAITS[name]) return AGENT_PORTRAITS[name]
  const norm = (s: string) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  const n = norm(name)
  for (const [k, v] of Object.entries(AGENT_PORTRAITS)) {
    if (norm(k) === n) return v
  }
  return undefined
}
